#include <stdio.h>

int main()
{
    int X, valor1, valor2,valor3;
    float seg = 0 , min = 0 , hora = 0 ;
    scanf("%d", &X);

    if (X < 60)
    {
        seg = X ;
        min = 0;
        hora = 0;
    }
    if (X >= 60)
    {
        valor1 = X % 60;
        valor2 = X / 60;
        if (valor1 == 0 && valor2 < 60)
        {
            seg = 0;
            min = valor2;
            hora = 0;
        }
        if (valor1 != 0)
        {
            seg = valor1;
        }
        if (valor2 >= 60)
        {
            valor3 = valor2 / 60;
            valor2 %= 60;
            if (valor2 == 0)
            {
                seg = 0;
                min = 0;
                hora = valor3;
            }
            if (valor2 != 0)
            {
                min = valor2;
                hora = -valor3 + valor2;
            }
        }
    }
    printf("%2.0f:%2.0f:%2.0f\n",hora,min,seg);
    return 0;
}

