void handle_char(int c, int *not_zero) {

    switch (c) {
        case '\n':
            if (*not_zero) {
                *not_zero = false;
            } else {
                putchar('0');
            }
            putchar(c);
            break;
        case '0':
            if (*not_zero) 
                putchar(c);
            break;
        default:
            *not_zero = true;
            putchar(c);
    }

}

