    enum all_states state = FORA;
    int current;

    while ((current = getchar()) != EOF) {
        if (state == FORA) {
            if (nonzero(current)) {
                putchar(current);
                state = DENTRO;
            }
            else if (current == '0') state = ZERO;
            else putchar(current);
        }
