int soma_algarismos(int num)
{
    int soma = 0, digito;
    while(num > 0)
    {
        digito = num % 10;
        num /= 10;
        soma += digito;
    }
    return soma;
}

int divisivel_por_9(int num)
{
    int soma = soma_algarismos(num);
    if(soma == 9)
        return 0;
    else if(soma < 10)
        return 1;
    else
        return divisivel_por_9(soma);
}

