#include <stdio.h>
#include <stdlib.h>

void operacao(char sinal,int *result, int num)
{
    if (sinal == '-')
        *result -= num;
    else if (sinal == '+')
        *result += num;
}

int main ()
{
    char c, sinal = '+';
    int num=0, result=0;

    while ((c = getchar()) != '\n'){

        if (c == '+' || c == '-'){
            sinal = c;
            c = getchar();
        }
        else{
            if (c >= '0' && c <= '9')
                num = num*10 + c - 48;
            else if (sinal != ' '){
                operacao(sinal, &result, num);
                sinal = ' ';
                num=0;
            }
        }
    }
    operacao(sinal, &result, num);

    printf("Resultado:%d\n", result);

    return 0;
}

#include <stdio.h>

int its_prime(int n){
    int i = 1, contador = 0;

    while (i <= n){
        if (n%i == 0)
            contador +=1;
        i++;
    }
    if (contador == 2)
        return 1;

    return 0;
}


int main(){

    int n, v = 1;
    scanf("%d", &n);
    while (v <= n){
        if (its_prime(v))
            printf("%d\t", v);
        v++;
    }

    return 0;



}

