int CharToNumber(char k){
    int contador=1;
    int resultado, i, n;
    char numeros[20];
    char c=k;
    resultado=0;
    numeros[0]=c;
    c=getchar();
    while (c!='\n' && c!=' ' && c!=EOF) 
    {
        numeros[contador]=c;
        contador++;
        c=getchar();
    }
    n=contador;
    for ( i = 0; i < n; i++)
    {
        resultado+=CharToInt(numeros[i])*10^contador;
        contador--;
    }
    return resultado;
}

int main(){
    char c;
    int soma=0;
    c=getchar();
    if (c>='0' && c<='9')
    {
        soma+=CharToNumber(c);
    }

    while ((c=getchar())!=EOF)
    {
        if (c=='+')
        {
            c=getchar();
            c=getchar();
            soma+=CharToNumber(c);
        }
        else if(c=='-'){
            c=getchar();
            c=getchar();
            soma-=CharToNumber(c);
        }

    }
    printf("%d\n",soma);

    return 0;
}

