    int c, i = 0;

    while ( (c = getchar()) != EOF && c != ' ' && c != '\n' && i < MAX - 1)
    {
        s[i] = c;
        i++;
    }
    s[i] = '\0';
    return i;
}

int main() {
    char n1[MAX], n2[MAX];
    int i;
    leLinha(n1);
    leLinha(n2);
    for ( i = 0;n1[i] != '\0' && n2[i] != '\0'; i++)
    {
        if (n1[i] > n2[i]) {
            printf("%s\n", n1);
            break;
        } else {
            printf("%s\n", n2);
            break;
        }
    }

    return 0;
}

#include <stdio.h>

#define MAX 80

int main() {
    char s[MAX];
    int first = 0, second = 0;

    if (fgets(s, MAX, stdin) != NULL) {
        while (s[second] != ' ') second++;
        second++;
        for (first = 0; first < second - 1; first++) {
            if (s[first] > s[second]) {
                second = 0;
                break;
            } else if (s[first] < s[second]) {
                first = 0;
                break;
            } else putchar(s[first]);
            first++;
            second++;
        }
        while (s[first + second] != ' ' && s[first + second] != '\n') {
            putchar(s[first + second]);
            first++;
        }
        putchar('\n');
    }

    return 0;
}

#include <stdio.h>

void imprimir_lista(char s[]) {
    int i = 0;
    while (s[i] != '\0') {
        putchar(s[i]);
        i++;
    }
    putchar('\n');
}
void maior(char s1[], char s2[]) {
    int i = 0;
    while (s1[i] != '\0' && s2[i] != '\0') {
        if (s1[i] > s2[i]) {
            imprimir_lista(s1);
            return;
        } else {
            imprimir_lista(s2);
            return;
        }
        i++;    
    }
}

int main() {
    char s1[101], s2[101];
    scanf("%s", s1);
    scanf("%s", s2);
    maior(s1, s2);
    return 0;
}

