        s[i] = c;
        i++;
    }
    s[i] = '\0';
    return i;
}

char *maior(char n1[], char n2[]){
    int i;

    for(i = 0; n1[i] == n2[i] && n1[i] != '\0'; i++){
        if (n1[i] > n2[i]){
            return n1;
        }

    }
    return n2;
}

int main(){
